import "jest";

import {configure} from "enzyme";
import * as Adapter from "enzyme-adapter-react-16";

declare const global: any;

configure({adapter: new Adapter()});
global.requestAnimationFrame = (callback) => {
  setTimeout(callback, 0);
};

const matchMedia = () => {
  return {
    matches: false,
    addListener: null,
    removeListener: null,
  };
};

global.matchMedia = global.matchMedia || matchMedia;

import {mount} from "enzyme";
import * as React from "react";
import {stub} from "sinon";
import {Themes} from "../Themes";

describe("Themes spec", () => {
    it("should render proper", () => {
        const channel = {
            on: stub(),
            emit: stub(),
            removeListener: stub(),
        };

        const component = mount(<Themes api={null} channel={channel} active={true} />);
        expect(component.render()).toMatchSnapshot();
        expect(channel.on.calledOnce).toBeTruthy();
        expect(channel.emit.notCalled).toBeTruthy();

        component.unmount();
        expect(channel.removeListener.calledOnce).toBeTruthy();
    });
});

module.exports = {
  transform: {
    "^.+\\.tsx?$": "ts-jest",
  },
  globals: {
    "ts-jest": {
      compiler: "typescript",
    },
  },
  testRegex: "(src/__tests__/.*|(\\.|/)(test|spec))\\.(tsx?)$",
  testPathIgnorePatterns: [
    "/node_modules/",
    "./src/__tests__/setup",
    "dist",
  ],
  setupFiles: ["./src/__tests__/setup/setupTests.ts"],
  snapshotSerializers: ["enzyme-to-json/serializer"],
  moduleFileExtensions: ["js", "jsx", "json", "ts", "tsx"],
  coverageDirectory: "./coverage/",
  collectCoverage: true,
};

import {storiesOf} from "@storybook/react";
import * as React from "react";
import {Demo} from "./Demo";

storiesOf("Examples", module).add("Demo", () => <Demo />);

export {ThemesProvider} from "./ThemesProvider";
export {Themes} from "./Themes";
export {withThemesProvider} from "./withThemesProvider";

module.exports = function({config}) {
    config.module.rules.push({
        exclude: /node_modules/,
        loader: "awesome-typescript-loader",
        test: /\.(ts|tsx)$/,
    });
    config.resolve.extensions.push(".ts", ".tsx");
    return config;
